	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/v1/me/profile", wrapper.CreateProfile)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/v1/daily/{date}", wrapper.GetDaily)
